// The frame and the auth screens (docs/54), on the plain server and the database
// e2e/console_server.py seeded for this run: the CSP trial of every role's session (Lucide's
// icons, the account menu, the drawer, the toasts: nothing may be blocked), the whole flow by
// keyboard alone, and each new state photographed and checked by axe in both themes. The
// passwords were generated by playwright.config.ts.

import { expect, test, type Page } from "@playwright/test";
import { picturedAndChecked } from "./a11y";
import {
  ADMIN,
  APP_ADMIN,
  APP_READER,
  NO_ROLE,
  OPERATOR,
  ORG_READER,
  Scan,
  logIn,
  secret,
  sections,
  type Account,
} from "./session";

test.describe.configure({ mode: "serial" });

/** Every content-security-policy violation the page reports, gathered from its start. */
async function watchPolicy(page: Page): Promise<() => Promise<string[]>> {
  await page.addInitScript(() => {
    const seen: string[] = [];
    Object.assign(window, { policyViolations: seen });
    document.addEventListener("securitypolicyviolation", (event) => {
      seen.push(`${event.violatedDirective} ${event.blockedURI}`);
    });
  });
  return () =>
    page.evaluate(() => (window as unknown as { policyViolations: string[] }).policyViolations);
}

function accountButton(page: Page) {
  return page.getByRole("button", { name: /^Account:/ });
}

for (const who of [OPERATOR, ADMIN, ORG_READER, APP_ADMIN, APP_READER, NO_ROLE] as Account[]) {
  test(`CSP trial: ${who.username}'s session blocks nothing (icons, menu, sidebar)`, async ({
    page,
  }) => {
    const violations = await watchPolicy(page);
    const requests: string[] = [];
    page.on("request", (request) => requests.push(request.url()));
    await page.goto("/dashboard/");
    await logIn(page, who);
    const links = sections(page).getByRole("link");
    for (const label of await links.allTextContents()) {
      await sections(page).getByRole("link", { name: label, exact: true }).click();
      await expect(page.getByRole("navigation", { name: "Breadcrumb" })).toBeVisible();
    }
    await accountButton(page).click();
    await expect(page.getByRole("menu", { name: "Account" })).toBeVisible();
    await page.keyboard.press("Escape");
    await page.getByRole("button", { name: "Collapse the sidebar" }).click();
    await page.getByRole("button", { name: "Expand the sidebar" }).click();
    expect(await violations()).toEqual([]);
    // Nothing is fetched from another origin (no font, icon or script from elsewhere).
    const origin = new URL(page.url()).origin;
    expect(requests.filter((url) => !url.startsWith(origin) && !url.startsWith("data:"))).toEqual(
      [],
    );
  });
}

test("by keyboard alone: log in, skip to the content, the sidebar, the account menu, the theme, log out", async ({
  page,
}) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/channels");
  const form = page.getByRole("region", { name: "Log in", exact: true });
  // The focus starts on the username; Tab goes to the password, Enter sends the form.
  await expect(form.getByLabel("Username")).toBeFocused();
  await page.keyboard.type(ADMIN.username);
  await page.keyboard.press("Tab");
  await expect(form.getByLabel("Password", { exact: true })).toBeFocused();
  await page.keyboard.type(secret(ADMIN.second));
  await page.keyboard.press("Enter");
  await expect(page.getByRole("heading", { name: "Channels", level: 2 })).toBeVisible();

  // From the top of the page (a reload keeps the session), the first Tab reaches the skip link;
  // Enter moves the focus to the content.
  await page.reload();
  await expect(page.getByRole("heading", { name: "Channels", level: 2 })).toBeVisible();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("button", { name: "Skip to content" })).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.locator(".frame-content")).toBeFocused();

  // The sidebar's links by Tab and Enter, from the skip link on.
  const target = sections(page).getByRole("link", { name: "Incidents", exact: true });
  await page.getByRole("button", { name: "Skip to content" }).focus();
  for (let presses = 0; presses < 40; presses += 1) {
    if (await target.evaluate((element) => element === document.activeElement)) break;
    await page.keyboard.press("Tab");
  }
  await expect(target).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.getByRole("heading", { name: "Incidents", level: 2 })).toBeVisible();

  // The account menu: Enter opens it on its first item, arrows move, Enter chooses, Escape closes.
  await accountButton(page).focus();
  await page.keyboard.press("Enter");
  await expect(page.getByRole("menuitemradio", { name: "System" })).toBeFocused();
  await page.keyboard.press("ArrowDown");
  await page.keyboard.press("ArrowDown");
  await expect(page.getByRole("menuitemradio", { name: "Dark" })).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  await page.keyboard.press("Escape");
  await expect(accountButton(page)).toBeFocused();
  // Back to System for the tests after this one.
  await page.keyboard.press("Enter");
  await page.keyboard.press("Enter");
  await page.keyboard.press("Escape");

  // The sidebar narrows and widens by keyboard.
  await page.getByRole("button", { name: "Collapse the sidebar" }).focus();
  await page.keyboard.press("Enter");
  await expect(page.getByRole("button", { name: "Expand the sidebar" })).toBeFocused();
  await page.keyboard.press("Enter");

  // Log out by keyboard: ArrowUp on the button opens the menu on its last item, Log out.
  await accountButton(page).focus();
  await page.keyboard.press("ArrowUp");
  await expect(page.getByRole("menuitem", { name: "Log out" })).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(form).toContainText("Logged out.");
  expect(await scan.leaks(page)).toEqual([]);
});

test("each new state, photographed and checked by axe in both themes", async ({
  page,
}, testInfo) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  const form = page.getByRole("region", { name: "Log in", exact: true });
  await picturedAndChecked(page, testInfo, "frame-login");

  // A refused login: the gateway's one answer, with the lockout rule.
  await form.getByLabel("Username").fill(ADMIN.username);
  await form.getByLabel("Password", { exact: true }).fill("not-the-password");
  await form.getByRole("button", { name: "Log in" }).click();
  await expect(form.getByRole("alert")).toContainText("locked for 15 minutes");
  await picturedAndChecked(page, testInfo, "frame-login-refused");

  // The password shown (a text of no account, so no secret is on the page).
  await form.getByLabel("Password", { exact: true }).fill("shown-example-text");
  await form.getByRole("button", { name: "Show password" }).click();
  await expect(form.getByLabel("Password", { exact: true })).toHaveAttribute("type", "text");
  await picturedAndChecked(page, testInfo, "frame-login-shown");
  await form.getByRole("button", { name: "Hide password" }).click();
  await form.getByLabel("Password", { exact: true }).fill("");

  await logIn(page, ADMIN, scan);
  await accountButton(page).click();
  await expect(page.getByRole("menu", { name: "Account" })).toBeVisible();
  await picturedAndChecked(page, testInfo, "frame-account-menu");
  await page.keyboard.press("Escape");

  await page.getByRole("button", { name: "Collapse the sidebar" }).click();
  await picturedAndChecked(page, testInfo, "frame-sidebar-collapsed");
  await page.getByRole("button", { name: "Expand the sidebar" }).click();

  // A change's result as a toast: a preset that only tightens (no step-up).
  await sections(page).getByRole("link", { name: "Application settings", exact: true }).click();
  await page.getByRole("combobox", { name: "Application", exact: true }).selectOption("app-two");
  const presets = page.getByRole("region", { name: "Presets", exact: true });
  await presets.getByRole("button", { name: "Apply cheap" }).click();
  const toast = page.locator(".toasts").getByRole("status");
  await expect(toast).toContainText("Applied cheap");
  await picturedAndChecked(page, testInfo, "frame-toast");
  await toast.getByRole("button", { name: "Dismiss" }).click();
  await expect(toast).toHaveCount(0);
  expect(await scan.leaks(page)).toEqual([]);
});

test("a phone: the sidebar is a drawer, opened from the top bar and closed by a link", async ({
  page,
}, testInfo) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/dashboard/");
  await logIn(page, ORG_READER);
  await expect(page.locator(".sidebar")).toBeHidden();
  // The page is no wider than the phone: a wide table scrolls in its box, and nothing positioned
  // inside it (a dash's hidden words) escapes the box.
  await expect(page.getByRole("table", { name: "Applications" })).toBeVisible();
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth),
  ).toBeLessThanOrEqual(0);
  await page.getByRole("button", { name: "Open the navigation" }).click();
  const drawer = page.getByRole("dialog", { name: "Navigation" });
  await expect(drawer).toBeVisible();
  await expect(drawer.getByRole("navigation", { name: "Sections" })).toBeVisible();
  await picturedAndChecked(page, testInfo, "frame-phone-drawer");
  await drawer.getByRole("link", { name: "Incidents", exact: true }).click();
  await expect(drawer).toBeHidden();
  await expect(page.getByRole("heading", { name: "Incidents", level: 2 })).toBeVisible();
  await picturedAndChecked(page, testInfo, "frame-phone-incidents");
});
